mapper.select:
SELECT bucket_date::text AS bucket_date, SUM(cnt)::integer AS cnt FROM (
    SELECT DATE(l.create_time) AS bucket_date, COUNT(*)::integer AS cnt
    FROM crm_lead l
    WHERE l.sid = #{eventId}
      AND l.create_time >= #{dateFrom} AND l.create_time <= #{dateTo}
    GROUP BY DATE(l.create_time)
    UNION ALL
    SELECT DATE(w.create_time), COUNT(*)::integer
    FROM crm_wecom_external_contact w
    WHERE w.crm_event_id = #{eventId}
      AND w.create_time >= #{dateFrom} AND w.create_time <= #{dateTo}
    GROUP BY DATE(w.create_time)
    UNION ALL
    SELECT DATE(a.started_date), COUNT(*)::integer
    FROM crm_activity a
    WHERE a.channel = 'wechat_mp'
      AND a.event_type IN ('channel.wechat_mp.follow', 'channel.wechat_mp.scan')
      AND a.started_date >= #{dateFrom} AND a.started_date <= #{dateTo}
      AND (
          a.context->>'crm_event_id' = #{eventId}
          OR EXISTS (
              SELECT 1 FROM crm_wechat_mp_qrcode q
              WHERE q.crm_event_id = #{eventId}
                AND (
                    a.context->>'scene_str' = q.scene_str
                    OR a.payload->>'event_key' = 'qrscene_' || q.scene_str
                )
          )
      )
    GROUP BY DATE(a.started_date)
) sub GROUP BY bucket_date ORDER BY bucket_date

SELECT DATE(l.create_time)::text AS bucket_date, COUNT(*)::integer AS cnt
FROM crm_lead l
WHERE l.sid = #{eventId}
  AND l.create_time >= #{dateFrom} AND l.create_time <= #{dateTo}
GROUP BY DATE(l.create_time)
ORDER BY bucket_date

SELECT bucket_date::text AS bucket_date, SUM(cnt)::integer AS cnt FROM (
    SELECT DATE(ch.create_time) AS bucket_date, COUNT(DISTINCT ch.lead_id)::integer AS cnt
    FROM crm_conversion_history ch
    WHERE ch.target_id = #{eventId}
      AND ch.conversion_type = 'Marketing Event'
      AND ch.create_time >= #{dateFrom} AND ch.create_time <= #{dateTo}
    GROUP BY DATE(ch.create_time)
    UNION ALL
    SELECT DATE(COALESCE(l.update_time, l.create_time)), COUNT(*)::integer
    FROM crm_lead l
    WHERE l.sid = #{eventId}
      AND LOWER(TRIM(l.status)) != 'initial'
      AND COALESCE(l.update_time, l.create_time) >= #{dateFrom}
      AND COALESCE(l.update_time, l.create_time) <= #{dateTo}
      AND NOT EXISTS (
          SELECT 1 FROM crm_conversion_history ch2
          WHERE ch2.lead_id = l.lead_id
            AND ch2.target_id = #{eventId}
            AND ch2.conversion_type = 'Marketing Event'
      )
    GROUP BY DATE(COALESCE(l.update_time, l.create_time))
) sub GROUP BY bucket_date ORDER BY bucket_date

SELECT bucket_date::text AS bucket_date, SUM(cnt)::integer AS cnt FROM (
    SELECT DATE(ch.create_time) AS bucket_date, COUNT(DISTINCT ch.target_id)::integer AS cnt
    FROM crm_conversion_history ch
    INNER JOIN crm_lead l ON l.lead_id = ch.lead_id
    WHERE l.sid = #{eventId}
      AND ch.conversion_type = 'Contact'
      AND ch.target_id IS NOT NULL AND ch.target_id != ''
      AND ch.create_time >= #{dateFrom} AND ch.create_time <= #{dateTo}
    GROUP BY DATE(ch.create_time)
    UNION ALL
    SELECT DATE(COALESCE(w.update_time, w.create_time)), COUNT(DISTINCT w.crm_contact_id)::integer
    FROM crm_wecom_external_contact w
    WHERE w.crm_event_id = #{eventId}
      AND w.crm_contact_id IS NOT NULL AND w.crm_contact_id != ''
      AND COALESCE(w.update_time, w.create_time) >= #{dateFrom}
      AND COALESCE(w.update_time, w.create_time) <= #{dateTo}
    GROUP BY DATE(COALESCE(w.update_time, w.create_time))
    UNION ALL
    SELECT DATE(MIN(a.started_date)), COUNT(DISTINCT f.contact_id)::integer
    FROM crm_wechat_mp_fan f
    INNER JOIN crm_activity a ON (
        a.context->>'openid' = f.open_id OR a.context->>'open_id' = f.open_id
    )
    WHERE f.contact_id IS NOT NULL AND f.contact_id != ''
      AND a.started_date >= #{dateFrom} AND a.started_date <= #{dateTo}
      AND (
          a.context->>'crm_event_id' = #{eventId}
          OR EXISTS (
              SELECT 1 FROM crm_wechat_mp_qrcode q
              WHERE q.crm_event_id = #{eventId}
                AND a.context->>'scene_str' = q.scene_str
          )
      )
    GROUP BY f.contact_id, DATE(a.started_date)
) sub GROUP BY bucket_date ORDER BY bucket_date

SELECT COALESCE(SUM(COALESCE(c.sign_amount, c.total_amount, c.amount, 0)), 0)
FROM crm_contract c
WHERE c.contact_id = #{contactId}
  AND c.sign_time IS NOT NULL
  AND c.sign_time >= #{windowStart}
  AND c.sign_time <= #{windowEnd}

SELECT COALESCE(SUM(o.amount), 0) FROM crm_opty o
WHERE o.contact_id = #{contactId}
  AND o.create_time >= #{windowStart}
  AND o.create_time <= #{windowEnd}
  AND ()
  AND NOT EXISTS (
      SELECT 1 FROM crm_contract c
      WHERE c.opty_id = o.opty_id AND c.opty_id IS NOT NULL AND c.opty_id != ''
  )

SELECT COALESCE(SUM(p.refund_amount), 0) FROM crm_paymentterm p
INNER JOIN crm_contract c ON c.contract_id = p.contract_id
WHERE c.contact_id = #{contactId}
  AND p.refunded_at IS NOT NULL
  AND p.refunded_at >= #{windowStart}
  AND p.refunded_at <= #{windowEnd}

SELECT MIN(ts) FROM (
    SELECT ch.create_time AS ts
    FROM crm_conversion_history ch
    INNER JOIN crm_lead l ON l.lead_id = ch.lead_id
    WHERE l.sid = #{eventId} AND ch.conversion_type = 'Contact' AND ch.target_id = #{contactId}
    UNION ALL
    SELECT COALESCE(w.update_time, w.create_time)
    FROM crm_wecom_external_contact w
    WHERE w.crm_event_id = #{eventId} AND w.crm_contact_id = #{contactId}
) t
